#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }
    // Parse shift value
    long shift = strtol(argv[1], NULL, 10);
    // Normalize shift to range 0-25 (mod 26)
    int shift_mod = (int)((shift % 26 + 26) % 26);
    const char *text = argv[2];
    size_t len = strlen(text);
    if (len > 1024) {
        puts("USAGE");
        return 0;
    }
    for (size_t i = 0; i < len; ++i) {
        unsigned char c = text[i];
        if (c >= 'A' && c <= 'Z') {
            c = (c - 'A' + shift_mod) % 26 + 'A';
        } else if (c >= 'a' && c <= 'z') {
            c = (c - 'a' + shift_mod) % 26 + 'a';
        }
        putchar(c);
    }
    putchar('\n');
    return 0;
}
